import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>PNG 转 JPG 以缩小文件出名，但省多少因图片而异。截图可能缩小 90%，简单图标反而可能变大。</p>\n<p>理解什么决定了节省，能帮你在转换前预测结果，选出保护重要内容的画质设置。</p>\n<p>这篇文章按图片类型诚实地看数字，用大白话讲清其中的取舍。想自己试一试，<a href=\"/zh/png-zhuan-jpg/\">PNG 转 JPG</a>能直接把图片转成轻量 JPG，还可以自定义背景底色。</p>\n<h2 id=\"why-png-is-big\">PNG 文件为什么这么大</h2>\n<p>PNG 是无损的，意味着它精确存储每个像素。这种精确要花字节，细节丰富的图片尤其如此，纹理和颜色变化无穷无尽。</p>\n<p>一张照片有几百万种微妙不同的颜色。PNG 必须描述每一种，JPG 却能把它们简化成眼睛几乎分辨不出的平滑渐变。</p>\n<p>噪点是隐藏的成本。相机颗粒、屏幕纹理、抗锯齿边缘都是看起来随机的数据，随机数据在任何无损格式里都很难压缩。</p>\n<p>截图是最糟糕的情况。整屏截图混合了照片、文字、渐变和界面元素，PNG 以完整保真度存储所有这些。</p>\n<h2 id=\"why-jpg-is-small\">JPG 文件为什么小这么多</h2>\n<p>JPG 是有损的，意味着它丢弃细节来省空间。它把附近像素分块，简化每个小块内部的颜色。</p>\n<p>平滑区域压得特别好。蓝天、白墙、虚化背景在 JPG 里只要很少字节，PNG 却仍要描述每个像素。</p>\n<p>画质设置控制简化的激进程度。85% 时简化看不见，50% 时就很明显了。</p>\n<p>照片和截图上，这笔交易非常划算。正常观看尺寸下，人眼看不到丢掉的细节，文件却缩小到十分之一。</p>\n<h2 id=\"savings-by-image-type\">按图片类型看节省</h2>\n<p>截图省得最多，通常 80% 到 90%。一张 5MB 的视网膜截图，85% 画质下变成 500KB 的 JPG，文字依然可读。</p>\n<p>存成 PNG 的照片能省 70% 到 85%。一张 12MB 的 PNG 照片变成 1.5MB 到 2MB 的 JPG，发邮件或上传都容易得多。</p>\n<p>简单图形省得最少，常常只有 30% 到 50%。纯色块的标志存成 PNG 本来就压得很好，JPG 没多少可省的空间。</p>\n<p>极小的单色图标可能反而变大。一张 20KB 的图标可能变成 25KB 的 JPG，因为 JPG 增加了简单图片不需要的头部开销。</p>\n<h2 id=\"quality-slider-maths\">画质滑块，实际怎么算</h2>\n<p>滑块范围 20% 到 100%，每档同时改变大小和画质。这个关系不是线性的，很多人都感到意外。</p>\n<p>从 100% 到 90%，文件常常小一半，肉眼看不出变化。这是整个范围里最划算的交易，90 是个好的起点。</p>\n<p>从 90% 到 80%，文件再小一半，仔细看才有轻微柔和。这是大多数截图和照片的最佳区间。</p>\n<p>从 80% 到 60%，省得越来越少、损伤越来越大。文字变模糊、边缘出现光晕、渐变出现色带，这笔交易不再值得。</p>\n<h2 id=\"text-at-each-quality\">每个画质档位的文字锐利度</h2>\n<p>90% 时，截图文字看起来基本完美。字母清晰，只有逐像素对比才能看出和 PNG 的差别。</p>\n<p>85% 时，正常阅读尺寸下文字依然干净。放大看字母边缘有轻微柔和，但没人会放大了读截图。</p>\n<p>75% 时，小字开始遭殃。菜单标签和细小印刷内容出现光晕，截图感觉略微失焦。</p>\n<p>60% 时，文字明显受损。字母洇进背景，截图看起来不专业，带文字的内容要避开这个档位。</p>\n<h2 id=\"photos-at-each-quality\">每个画质档位的照片</h2>\n<p>照片比截图更耐低画质。人像在 80% 时看起来干净，因为皮肤和头发很能藏压缩痕迹。</p>\n<p>风景要求更高。树叶、水面、远处建筑这类精细细节在 80% 以下会明显变软，整体画面看起来还行。</p>\n<p>产品照片要注意边缘。白底上的锐利产品轮廓在低画质下可能出现光晕，网店页面上看起来很廉价。</p>\n<p>照片上，80% 到 85% 是实际下限。再低，省得很少、损伤却看得见，这笔交易不划算。</p>\n<h2 id=\"when-savings-disappear\">节省什么时候消失</h2>\n<p>颜色少的简单图形省得很少。扁平图标或双色图表存成 PNG 本来就压得很好，JPG 没什么可简化的。</p>\n<p>很小的图片也省得很少。一张 30KB 的图片没多少数据可删，JPG 的头部开销会吃掉省下来的部分。</p>\n<p>噪点重的图片比预期省得少。噪点在编码器眼里是随机数据，随机数据两种格式都很难压缩。</p>\n<p>转好的文件只比原文件小一点，说明 PNG 本来就很高效。这张图片留着 PNG，跳过转换。</p>\n<h2 id=\"choosing-the-right-setting\">按任务选合适的设置</h2>\n<p>进文档的截图用 88% 到 90%。文字保持锐利，文件缩小 80%，文档看起来专业。</p>\n<p>上网站的照片用 80% 到 85%。图片看起来干净，页面加载快，省得也很多。</p>\n<p>交给有大小限制的表格的图片，从 85 开始、每步降五点，直到文件符合要求。每步后检查文字。</p>\n<p>要打印的图片用 92% 到 95%。打印会暴露屏幕看不出的瑕疵，单张重要图片多出来的体积不算什么。</p>\n<h2 id=\"comparing-before-after\">正确对比转换前后</h2>\n<p>别只看文件大小判断画质。文字读不出来的小文件没用，图片和更小的文件看起来一样的，大文件就是浪费。</p>\n<p>用“对比”查看器检查转好的 JPG 和原 PNG。放大重要的区域：文字、脸部、锐利边缘。</p>\n<p>按图片真实的显示尺寸检查，别放大了看。300% 放大下看得见的瑕疵，图片以 600 像素宽显示时根本不重要。</p>\n<p>用两个画质档位各转一次，直接对比。85% 和 90% 的差别常常看不见，小的那个文件就是正确的选择。</p>\n<h2 id=\"batch-savings\">批量节省加起来很快</h2>\n<p>一张截图省 4MB 感觉微不足道。五十张截图各省 4MB 就是 200MB，这是邮件发得出去和被退回的区别。</p>\n<p>网站最受益于批量节省。一个页面二十张 PNG 截图可能 60MB，JPG 版本 8MB，页面几秒加载完，而不是几分钟。</p>\n<p>存储也受益。照片档案从 PNG 转成 85% 的 JPG，能缩小 80%，腾出空间装好几年的新照片。</p>\n<p>每次转换后看批量汇总。它把所有文件的节省加起来，好的批量会显示一个惊人的数字，证明这番功夫值得。</p>\n<h2 id=\"when-not-to-convert\">什么时候根本别转</h2>\n<p>需要透明的标志别转。JPG 带不了透明，底色填充会在彩色背景上的标志周围放一个显眼的框。</p>\n<p>打算多次编辑的图片别转。JPG 每次保存都会叠加损伤，PNG 反复编辑不会损失。</p>\n<p>极小的图标别转。省得微乎其微，转出来的 JPG 可能比它取代的 PNG 还大。</p>\n<p>存档原稿别转。原 PNG 留着做原稿，交付时转副本，这样永远能回到完美的原文件。</p>\n<h2 id=\"webp-alternative\">值得了解的 WebP 替代方案</h2>\n<p>PNG 转换时，WebP 常常胜过 JPG，尤其截图。它更好地保留文字、保留透明，同等画质下文件更小。</p>\n<p>PNG 截图转 85% 的 WebP，通常比 JPG 版本更小、也更锐利。上网站时，WebP 是更好的目标。</p>\n<p>问题是兼容性。有些表格、打印机、老程序拒收 WebP，JPG 则哪里都行得通。</p>\n<p>目的地是网站时选 WebP。目的地不明或很老时选 JPG。<a href=\"/zh/png-zhuan-webp/\">PNG 转 WebP 工具</a>能处理上网的情况。</p>\n<h2 id=\"email-attachment-limits\">邮件附件限制</h2>\n<p>大多数邮件服务把附件上限设在 20MB 到 25MB，PNG 截图很快就能超。五张 5MB 的截图总共 25MB，邮件会被退回。</p>\n<p>把这些截图转成 85% 画质的 JPG，总共大约 4MB。邮件马上就能发出，收件人看到的图片是一样的。</p>\n<p>单张大截图，转换一次通常就能解决问题。一张 5MB 的 PNG 变成 500KB 的 JPG，远低于任何附件限制。</p>\n<p>图片特别多时，转换后把 JPG 打成一个压缩包。一个附件比十个好管理，收件人一次下载全部内容。</p>\n<p>发送前检查总大小，而不是发送后。看一眼附件大小，能避免你以为邮件发出去了、结果收到退信的挫败。</p>\n<h2 id=\"website-loading-speed\">网站加载速度</h2>\n<p>网站速度很大程度上取决于图片大小，PNG 照片是最严重的拖累之一。一个页面十张 PNG 照片可能 30MB，JPG 版本 4MB。</p>\n<p>访客马上就能感觉到差别。十秒加载的页面会丢读者，两秒加载的同一页面能留住他们。</p>\n<p>搜索引擎也注意到了。谷歌把页面速度算进排名，所以 JPG 图片的快速页面比 PNG 照片的慢速页面排名更好。</p>\n<p>网站上的 PNG 转成 80% 到 85% 画质的 JPG，或者转 WebP 能更小。图片看起来一模一样，页面感觉却快得多。</p>\n<p>转换前后测一下页面速度。PageSpeed Insights 这类工具能用具体数字显示改善，证明这番功夫值得。</p>\n<h2 id=\"storage-on-phone\">手机满了怎么办</h2>\n<p>手机里塞满 PNG 截图，会占用照片和应用需要的存储。转换必须留着的截图、删掉其余的，能腾出实实在在的空间。</p>\n<p>在手机设置里看截图用了多少空间。这个数字常常让人惊讶，几百 MB 绑在你忘了存在的图片上。</p>\n<p>留着的截图转 85% 画质的 JPG。文字保持可读，文件缩小 80%，手机又能喘口气了。</p>\n<p>不再需要的截图删掉。大多数是临时的，比如一次性验证码或聊天消息，全部留着是白白浪费空间。</p>\n<p>每月设个提醒清理截图。每月花五分钟清理，能防止缓慢累积最终塞满手机。</p>\n<h2 id=\"upload-limits-forms\">表格的上传限制</h2>\n<p>上传表格常常把图片上限设在 2MB 或 5MB，PNG 截图很容易超。一张 5MB 的 PNG 被退回，500KB 的 JPG 版本却能顺利上传。</p>\n<p>打开表格之前先转换图片。截止时间压力下的最后一刻转换最容易出错，提前转换留有检查结果的时间。</p>\n<p>除了大小限制，也看表格接受的格式。有些表格列出 JPG 和 PNG，却拒收 WebP，格式和大小一样重要。</p>\n<p>JPG 还是太大时，把画质降到 80% 再试一次。这一步常常能让文件小一半，肉眼几乎看不出变化。</p>\n<p>表格要求精确大小时，转换后用目标文件大小压缩工具。先转换，再压缩到精确上限，按这个顺序。</p>\n<h2 id=\"balancing-quality-batch\">批量里的画质平衡</h2>\n<p>图片类型混杂的批量，需要一个适合最弱文件的画质设置。带文字的截图需要 85% 或更高，照片 80% 也能接受。</p>\n<p>一批里截图和照片混在一起时，选 85%。截图保持可读，照片看起来干净，文件依然比 PNG 小得多。</p>\n<p>一批全是照片时，80% 是务实的选择。图片看起来和 PNG 一模一样，文件还比 85% 时更小。</p>\n<p>转换后检查最弱的文件，而不是最强的文件。80% 时看起来没问题的照片，证明不了小字截图也没问题。</p>\n<p>拿不准就按类型拆分批量。两个各有针对性设置的批量，胜过一个折中设置的批量，多花的一分钟值得更好的结果。</p>\n<p>数字讲的故事很简单：截图和照片大幅缩小，简单图形几乎不缩小，85% 以上的画质能保护文字。想看完整指南，请读<a href=\"/zh/blog/png-zhuan-jpg-wanquan-zhinan/\">PNG 转 JPG 完全指南</a>，分步操作请看<a href=\"/zh/blog/ruhe-ba-png-zhuancheng-jpg/\">如何把 PNG 转换成 JPG</a>。图片已经是 JPG、只需要更小时，<a href=\"/zh/\">图片压缩工具</a>是下一步。</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"截图用什么画质设置，体积和画质最平衡？","answer":"85% 是截图务实的最佳点。文字保持可读，文件缩小大约 80%，正常尺寸下图片看起来干净。降到 75% 省不了多少额外空间，小字却明显变软，这笔交易不划算。"},{"question":"为什么小图标转 JPG 后反而变大了？","answer":"JPG 增加了 PNG 对简单图片不需要的头部开销，扁平图标又没多少细节可供 JPG 简化。一张 20KB 的单色图标转成 JPG 可能多出几 KB。简单图形留着 PNG 就好，转换省不了什么。"},{"question":"照片用 90% 画质比 80% 明显更好吗？","answer":"正常观看尺寸下几乎没有差别。90% 的文件常常是 80% 的两倍大，放大细看之前两者看起来一模一样。网站照片用 80% 更明智，打印用 90% 或更高。"},{"question":"一文件夹 PNG 截图一次批量能缩小多少？","answer":"五十张 5MB 的截图，总共大约 250MB，85% 画质下转成 JPG 通常是 25MB 到 40MB。省了 85%，这就是文件夹发邮件轻松和发不出去的区别。批量汇总会显示精确总数。"},{"question":"画质降到 70% 以下有意义吗？","answer":"很少有意义，只有表格把上传上限设在 100KB 这类严格限制逼着你时才有。70% 以下文字变模糊、照片明显受损。文件必须这么小时，先考虑缩小尺寸，保画质的效果比压画质滑块更好。"},{"question":"网站用 PNG 转 JPG 好还是转 WebP 好？","answer":"WebP 通常更好，因为它更好地保留文字、保留透明，同等画质下文件比 JPG 更小。JPG 只在目的地不明或很老时胜出。现代网站，WebP 是正确的目标。"}];
